SELECT o.test_run_id, o.id, o.symbol, o.replay_stage, o.source_signal_id, o.generated_at, UNIX_TIMESTAMP(o.generated_at) AS gen_epoch, o.decision_code, o.evidence_count, o.evidence_score FROM execution_opportunity_test o WHERE o.symbol = 'DOGEUSDT' AND o.generated_at BETWEEN '2026-10-12 03:35:00' AND '2026-10-12 04:05:00' ORDER BY o.test_run_id, o.generated_at LIMIT 100;
SELECT w.test_run_id, w.id, w.symbol, w.entry_time, UNIX_TIMESTAMP(w.entry_time) AS entry_epoch, w.exit_reason, w.realized_pnl_usdt FROM wallet_position_test w WHERE w.symbol = 'DOGEUSDT' AND w.entry_time BETWEEN '2026-10-12 03:35:00' AND '2026-10-12 04:30:00' ORDER BY w.test_run_id, w.entry_time LIMIT 100